Le contrôle croisé annoncé au docstring (§D) n’existe pas : le résultat de parse_kill_restart_evidence est jeté et milestones_completed n’est testé que pour sa non-vacuité. Une chronologie M1→M1,M2,M3 et un long_run revendiquant uniquement UNRELATED obtiennent ALL CHECKS PASS. set_long_run_ready peut ainsi activer le projet avec des bundles qui ne décrivent pas les mêmes jalons.

Reproduction exécutée sur les sources originales au SHA 49007c0be862ae2809a98229508bbdcf12cb443d ; aucun correctif appliqué (mission de revue). À la racine du dépôt :
FACTORY_NO_REAL_ENGINE=1 PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import argparse, contextlib, copy, hashlib, io, json, os, runpy, subprocess, sys, tempfile
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch, Mock
ROOT = Path.cwd()
sys.path.insert(0, str(ROOT))
from factory_v2 import verify_reshape_receipt as reshape
from factory_v2 import verify_simplification_batch as simplify
from factory_v2 import worker_lease as wl
from factory_v2.worker_heartbeat import WorkerHeartbeat
from factory_v2 import verify_long_run as longrun


def write(p, value):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(value))
    return p

def git(repo,*a):
    p=subprocess.run(['git','-C',str(repo),'-c','user.email=test@example.com','-c','user.name=Test','-c','commit.gpgsign=false',*a],capture_output=True,text=True)
    assert p.returncode == 0, p.stderr
    return p.stdout.strip()

def ready_fixture(p):
    kr={'pid_a':101,'pid_b':102,'birth_a':'a','birth_b':'b','milestones_before':['M1'],'milestones_after':['M1','M2','M3'],'fault_record':{'outcome':'INJECTED'}}
    cas={'mission_id':'m','first_outcome':'CAS_ALLOWED','second_outcome':'CAS_DUPLICATE'}
    for name,obj in [('kr',kr),('cas',cas)]: write(p/f'{name}.json',obj)
    receipt={'schema':'lr5-preflight-receipt/v2','integration_sha':git(ROOT,'rev-parse','HEAD'),'observations':{k:{'evidence_path':str(p/f'{v}.json'),'evidence_sha256':hashlib.sha256((p/f'{v}.json').read_bytes()).hexdigest()} for k,v in [('kill_restart_recovery','kr'),('cas_double_dispatch','cas')]}}
    preflight={'status':'PASS','manifest_sha':'a'*64}
    lr={'status':'PASS','crashed':True,'restarted':True,'daemon_identities':[{'pid':101,'birth':'a'},{'pid':102,'birth':'b'}],'milestones_completed':['M1','M2','M3']}
    for name,obj in [('receipt',receipt),('preflight',preflight),('longrun',lr)]: write(p/f'{name}.json',obj)
    return receipt,lr

def run_ready(p):
    a=[sys.executable,'-m','factory_v2.verify_long_run_ready','--repo-dir',str(ROOT),'--project-dir',str(p),'--receipt',str(p/'receipt.json'),'--preflight',str(p/'preflight.json'),'--long-run',str(p/'longrun.json')]
    return subprocess.run(a,capture_output=True,text=True,cwd=ROOT)

def ready_unrelated_milestones(p):
    _,lr=ready_fixture(p);lr['milestones_completed']=['UNRELATED'];write(p/'longrun.json',lr)
    r=run_ready(p);assert r.returncode==0,r.stdout+r.stderr
    return 'verifier_rc=0; timeline=M1,M2,M3; long_run=UNRELATED; ALL CHECKS PASS'

with tempfile.TemporaryDirectory(prefix='review-m6-') as tmp:
    result=ready_unrelated_milestones(Path(tmp))
print('TEST ready_unrelated_milestones: rc=0; ' + result)
